Here is the commit message:
btrfs: send: check for inline extents in
 range_is_hole_in_parent()

Before accessing the disk_bytenr field of a file extent item we need
to check if we are dealing with an inline extent.
This is because for inline extents their data starts at the offset of
the disk_bytenr field. So accessing the disk_bytenr
means we are accessing inline data or in case the inline data is less
than 8 bytes we can actually cause an invalid
memory access if this inline extent item is the first item in the leaf
or access metadata from other items.

Fixes: 82bfb2e7b645 ("Btrfs: incremental send, fix unnecessary hole writes for sparse files")
Reviewed-by: Filipe Manana <fdmanana@suse.com>
Signed-off-by: Qu Wenruo <wqu@suse.com>
Reviewed-by: David Sterba <dsterba@suse.com>
Signed-off-by: David Sterba <dsterba@suse.com>

Here is the root cause:
The function `range_is_hole_in_parent()` in `fs/btrfs/send.c` does not check whether a file extent item is inline before accessing its `disk_bytenr` field. For inline extents, the `disk_bytenr` field marks the start of inline data, not a disk address. Reading it can result in interpreting inline data as a disk address or, if the inline data is shorter than 8 bytes, causing an invalid memory access (especially if the inline extent item is the first item in a leaf or if it overruns into adjacent metadata). This leads to incorrect hole detection or crashes.

Here is the patch:

 static int range_is_hole_in_parent(struct send_ctx *sctx,
 				   const u64 start,
 				   const u64 end)
 {
 	BTRFS_PATH_AUTO_FREE(path);
 	struct btrfs_key key;
 	struct btrfs_root *root = sctx->parent_root;
 	u64 search_start = start;
 	int ret;

 	path = alloc_path_for_send();
 	if (!path)
 		return -ENOMEM;

 	key.objectid = sctx->cur_ino;
 	key.type = BTRFS_EXTENT_DATA_KEY;
 	key.offset = search_start;
 	ret = btrfs_search_slot(NULL, root, &key, path, 0, 0);
 	if (ret < 0)
 		return ret;
 	if (ret > 0 && path->slots[0] > 0)
 		path->slots[0]--;

 	while (search_start < end) {
 		struct extent_buffer *leaf = path->nodes[0];
 		int slot = path->slots[0];
 		struct btrfs_file_extent_item *fi;
 		u64 extent_end;

 		if (slot >= btrfs_header_nritems(leaf)) {
 			ret = btrfs_next_leaf(root, path);
 			if (ret < 0)
 				return ret;
 			if (ret > 0)
 				break;
 			continue;
 		}

 		btrfs_item_key_to_cpu(leaf, &key, slot);
 		if (key.objectid < sctx->cur_ino ||
 		    key.type < BTRFS_EXTENT_DATA_KEY)
 			goto next;
 		if (key.objectid > sctx->cur_ino ||
 		    key.type > BTRFS_EXTENT_DATA_KEY ||
 		    key.offset >= end)
 			break;

 		fi = btrfs_item_ptr(leaf, slot, struct btrfs_file_extent_item);
 		extent_end = btrfs_file_extent_end(path);
 		if (extent_end <= start)
 			goto next;
+		if (btrfs_file_extent_type(leaf, fi) == BTRFS_FILE_EXTENT_INLINE)
+			return 0;
 		if (btrfs_file_extent_disk_bytenr(leaf, fi) == 0) {
 			search_start = extent_end;
 			goto next;
 		}
 		return 0;
 next:
 		path->slots[0]++;
 	}
 	return 1;
 }



